using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace RaceDay.Api.Controllers;
[Authorize][Route("api")]
public class EnrolmentsController(RaceDayContext db):ApiControllerBase {
 /// <summary>Enter a category as a Participant, subject to capacity and uniqueness.</summary>
 [Authorize(Roles="Participant")][HttpPost("categories/{categoryId:int}/enrolments")]public async Task<IActionResult> Create(int categoryId,EnrolDto dto){var c=await db.Categories.Include(x=>x.Event).FirstOrDefaultAsync(x=>x.CategoryId==categoryId);if(c==null)return NotFound();if(c.Event.Status!="Open")return BadRequest("Event is not open for entries.");if(dto.RaceNumber is <=0)return BadRequest("Race number must be positive.");if(await db.Enrolments.AnyAsync(x=>x.CategoryId==categoryId&&x.UserId==CurrentUserId))return Conflict("Already entered in this category.");if(await db.Enrolments.CountAsync(x=>x.CategoryId==categoryId&&x.Status!="Cancelled")>=c.MaxParticipants)return Conflict("Category is full.");if(dto.RaceNumber.HasValue&&await db.Enrolments.AnyAsync(x=>x.RaceNumber==dto.RaceNumber))return Conflict("Race number already assigned.");var e=new Enrolment{CategoryId=categoryId,UserId=CurrentUserId,RaceNumber=dto.RaceNumber};db.Enrolments.Add(e);await db.SaveChangesAsync();return StatusCode(201,new{enrolmentId=e.EnrolmentId,status=e.Status});}
 /// <summary>View your own entries (Participant only).</summary>
 [Authorize(Roles="Participant")][HttpGet("users/me/enrolments")]public async Task<IActionResult> Mine()=>Ok(await db.Enrolments.Where(x=>x.UserId==CurrentUserId).ToListAsync());
 /// <summary>See enrolments for an event you organise.</summary>
 [Authorize(Roles="Organiser")][HttpGet("events/{eventId:int}/enrolments")]public async Task<IActionResult> EventEntries(int eventId){var ev=await db.Events.FindAsync(eventId);if(ev==null)return NotFound();if(ev.OrganiserId!=CurrentUserId)return Forbid();return Ok(await db.Enrolments.Where(x=>x.Category.EventId==eventId).ToListAsync());}
 /// <summary>Update an enrolment if you own it, or organise its event.</summary>
 [HttpPut("enrolments/{enrolmentId:int}")]public async Task<IActionResult> Update(int enrolmentId,UpdateEnrolmentDto dto){var e=await db.Enrolments.Include(x=>x.Category).ThenInclude(x=>x.Event).FirstOrDefaultAsync(x=>x.EnrolmentId==enrolmentId);if(e==null)return NotFound();if(e.UserId!=CurrentUserId&&e.Category.Event.OrganiserId!=CurrentUserId)return Forbid();if(!new[]{"Registered","Confirmed","Cancelled"}.Contains(dto.Status)||dto.RaceNumber is <=0)return BadRequest("Invalid status or race number.");if(dto.RaceNumber.HasValue&&await db.Enrolments.AnyAsync(x=>x.EnrolmentId!=enrolmentId&&x.RaceNumber==dto.RaceNumber))return Conflict("Race number in use.");if(e.Status=="Cancelled"&&dto.Status!="Cancelled"&&await db.Enrolments.CountAsync(x=>x.CategoryId==e.CategoryId&&x.Status!="Cancelled")>=e.Category.MaxParticipants)return Conflict("Category is full.");e.Status=dto.Status;e.RaceNumber=dto.RaceNumber;await db.SaveChangesAsync();return Ok(new{e.EnrolmentId,e.CategoryId,e.Status,e.RaceNumber});}
 /// <summary>Cancel an enrolment, retaining the historical record.</summary>
 [HttpDelete("enrolments/{enrolmentId:int}")]public async Task<IActionResult> Cancel(int enrolmentId){var e=await db.Enrolments.Include(x=>x.Category).ThenInclude(x=>x.Event).FirstOrDefaultAsync(x=>x.EnrolmentId==enrolmentId);if(e==null)return NotFound();if(e.UserId!=CurrentUserId&&e.Category.Event.OrganiserId!=CurrentUserId)return Forbid();if(await db.Results.AnyAsync(x=>x.EnrolmentId==enrolmentId))return Conflict("An enrolment with results cannot be cancelled.");e.Status="Cancelled";await db.SaveChangesAsync();return NoContent();}
}
